mapper.update:
UPDATE t_period_close
SET status = #{status}, active_slot = #{activeSlot}, close_hash = #{closeHash}, checker_id = #{checkerId},
    version = version + 1, update_time = #{now}
WHERE id = #{close.id} AND status = #{close.status} AND version = #{close.version}

mapper.select:
SELECT c.id period_close_id, c.period_id, c.close_no, c.close_type, c.status, c.maker_id, c.checker_id, c.close_hash, c.create_time,
       (SELECT s.step_type FROM t_close_step s WHERE s.period_close_id = c.id AND s.status = 'FAILED' ORDER BY s.step_no LIMIT 1) failed_step_type
FROM t_period_close c
WHERE c.period_id = #{periodId}
ORDER BY c.close_no DESC
LIMIT #{size} OFFSET #{offset}

